(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-796":{scenario:{company:"Công ty Du lịch Hành Trình Ngọc Lam",supervisor:{name:"Phan Nhật Linh",role:{vi:"Trưởng nhóm Hướng dẫn viên",en:"Head of Tour Guides"}},ref_code:"GD-1407",title:{vi:"Thuyết minh chính xác. Quyết toán minh bạch. An toàn trên hết.",en:"Accurate commentary. Transparent settlement. Safety first."},brief:{vi:"Bạn dẫn đoàn 18 khách Pháp (15 người lớn, 3 trẻ em 8-10 tuổi) tham quan Quần thể danh thắng Tràng An. Vé tham quan kèm đò: người lớn 250.000 đồng, trẻ em bằng 50% giá người lớn; hướng dẫn viên có thẻ hành nghề được miễn vé (số liệu mô phỏng). Thẻ thuyết minh nháp GD-1407 ghi sai loại hình di sản và bảng quyết toán ghi sai tổng tiền vé. Sửa hai trường rồi lập báo cáo có căn cứ.",en:"You are guiding 18 French guests (15 adults, 3 children aged 8-10) at the Trang An Landscape Complex. Entry with boat ride: adults 250,000 VND, children 50% of the adult price; a licensed guide enters free (training figures). Draft commentary card GD-1407 has the wrong heritage type and the settlement sheet has the wrong ticket total. Correct both fields and write an evidence-based report."},reference_title:{vi:"Hồ sơ điểm đến & bảng quyết toán đã duyệt · GD-1407",en:"Approved destination file & settlement sheet · GD-1407"},fields:[{id:"HERITAGE",label:{vi:"Loại hình di sản thế giới UNESCO",en:"UNESCO World Heritage type"},initial:"Natural",expected:"Mixed",choices:["Cultural","Natural","Mixed"],reference:"Hồ sơ điểm đến đã kiểm chứng",hint:{vi:"Xem Tràng An được ghi danh năm 2014 theo những tiêu chí nào: chỉ tiêu chí thiên nhiên hay cả tiêu chí văn hóa.",en:"Check which criteria Trang An was inscribed under in 2014: natural criteria only, or cultural ones as well."}},{id:"TICKET_TOTAL",label:{vi:"Tổng tiền vé tham quan (VND)",en:"Total entry tickets (VND)"},initial:"4750000",expected:"4125000",reference:"Bảng quyết toán tạm ứng tour",ref_value:{vi:"15 người lớn x 250.000 đồng; 3 trẻ em giá 50%; hướng dẫn viên miễn vé (mô phỏng)",en:"15 adults x 250,000 VND; 3 children at 50%; guide free (training)"},hint:{vi:"Tính riêng vé người lớn, vé trẻ em và không mua vé cho hướng dẫn viên có thẻ.",en:"Price adult and child tickets separately and buy no ticket for the licensed guide."}}],sop32:{vi:"Tổng tiền vé = số người lớn x giá người lớn + số trẻ em x giá người lớn x 50%; hướng dẫn viên có thẻ hành nghề không mua vé; chỉ quyết toán khoản có vé, hóa đơn hợp lệ (số liệu mô phỏng).",en:"Ticket total = adults x adult price + children x adult price x 50%; a licensed guide buys no ticket; settle only items with valid tickets or invoices (training figures)."},context:{label:"TOUR FILE / GD-1407",metrics:[{label:{vi:"Người lớn / trẻ em",en:"Adults / children"},value:"15 / 3"},{label:{vi:"Giá vé người lớn",en:"Adult ticket"},value:"250,000 VND"},{label:{vi:"Giá vé trẻ em",en:"Child ticket"},value:"50%"}]},crisis:{vi:"Có cảnh báo dông lốc, Ban quản lý tạm dừng một tuyến đò. Một người chở đò tư nhân mời đoàn đi tuyến khác ngoài bến, không có áo phao, giá rẻ; trưởng đoàn khách nói: “Đi thôi, đừng để khách thất vọng.”",en:"A thunderstorm warning is issued and the site management suspends one boat route. A private boatman offers another route outside the pier, cheap and with no life jackets; the group leader says: “Let's go, don't disappoint the guests.”"},options:{safe:{vi:"Không đưa khách lên đò không phép, thiếu áo phao; báo điều hành tour, giải thích rõ với khách và đổi sang hoạt động thay thế an toàn theo hướng dẫn của Ban quản lý.",en:"Do not put guests on an unlicensed boat without life jackets; inform tour operations, explain clearly to guests and switch to a safe alternative per site management guidance."},shortcut:{vi:"Cho đoàn đi đò tư nhân cho đúng lịch trình và dặn khách ngồi yên trên đò.",en:"Take the private boat to keep the itinerary and tell guests to sit still."},wait:{vi:"Để trưởng đoàn khách tự quyết, mình đứng chờ ở bến và không báo ai.",en:"Let the group leader decide, wait at the pier and inform no one."}},questions:{vi:["Vì sao bạn sửa loại hình di sản trên thẻ thuyết minh? Căn cứ nào chứng minh lựa chọn đó?","Trình bày cách tính tổng tiền vé và cách xử lý khi điều kiện an toàn trên tuyến tham quan không bảo đảm."],en:["Why did you change the heritage type on the commentary card? Which source supports your choice?","Explain how you calculated the ticket total and how you act when safety conditions on a route are not met."]},hints:{vi:["Đối chiếu thẻ thuyết minh với hồ sơ ghi danh của UNESCO, chú ý nhóm tiêu chí được công nhận.","Theo SOP mục 3.2: tách khách theo người lớn, trẻ em và kiểm tra ai được miễn vé.","Đọc lại SOP mục 4.2: an toàn của khách đứng trên lịch trình, mọi thay đổi phải báo điều hành."],en:["Compare the card with the UNESCO inscription file and note which criteria groups were recognised.","Per SOP 3.2: split guests into adults and children and check who enters free.","Re-read SOP 4.2: guest safety comes before the itinerary; report every change to operations."]}},learning:{summary:{vi:"Hướng dẫn viên du lịch quốc tế dẫn đoàn khách nước ngoài hoặc khách Việt Nam ra nước ngoài, thuyết minh lịch sử, văn hóa, thiên nhiên bằng ngoại ngữ, giữ lịch trình, quản lý đoàn, quyết toán chi phí và xử lý sự cố. Người hướng dẫn viên là gương mặt của điểm đến và của doanh nghiệp, chịu trách nhiệm trực tiếp về an toàn và trải nghiệm của khách. Nghề đòi hỏi kiến thức rộng, kiểm chứng thông tin, ngoại ngữ vững, sức khỏe tốt và đạo đức nghề nghiệp.",en:"An international tour guide leads foreign visitors in Vietnam or Vietnamese travellers abroad, giving commentary on history, culture and nature in a foreign language, keeping the itinerary, managing the group, settling expenses and handling incidents. The guide is the face of the destination and the company and is directly responsible for guest safety and experience. The role needs broad, verified knowledge, strong languages, good stamina and professional ethics."},responsibilities:{vi:["Nghiên cứu, kiểm chứng nội dung thuyết minh cho từng điểm đến trước mỗi tour.","Đón khách, kiểm đếm quân số, giữ lịch trình và phối hợp xe, nhà hàng, khách sạn.","Thuyết minh bằng ngoại ngữ, điều chỉnh nội dung theo văn hóa và mối quan tâm của khách.","Bảo đảm an toàn đoàn, theo dõi thời tiết, xử lý khách ốm, lạc, mất giấy tờ.","Quyết toán tạm ứng có chứng từ hợp lệ và báo cáo tour cho điều hành."],en:["Research and verify commentary for each destination before every tour.","Meet guests, run head counts, keep the itinerary and coordinate coaches, restaurants and hotels.","Deliver commentary in a foreign language, adapting to guests' culture and interests.","Keep the group safe, watch the weather and handle illness, lost guests and lost documents.","Settle the cash advance with valid receipts and report on the tour to operations."]},competencies:[{name:{vi:"Thuyết minh có kiểm chứng",en:"Verified commentary"},desc:{vi:"Dùng nguồn chính thống, phân biệt sự kiện với truyền thuyết và cập nhật thông tin mới.",en:"Use official sources, separate facts from legends and keep information current."}},{name:{vi:"Quản lý đoàn",en:"Group management"},desc:{vi:"Kiểm đếm quân số, điều phối thời gian và giữ đoàn gắn kết, đúng giờ.",en:"Run head counts, manage time and keep the group together and on schedule."}},{name:{vi:"Giao tiếp liên văn hóa",en:"Cross-cultural communication"},desc:{vi:"Hiểu thói quen, kỳ vọng của từng thị trường khách và truyền đạt văn hóa Việt Nam tự nhiên.",en:"Understand each market's habits and expectations and present Vietnamese culture naturally."}},{name:{vi:"An toàn & sơ cứu",en:"Safety & first aid"},desc:{vi:"Đánh giá rủi ro tại điểm, sơ cứu cơ bản và kích hoạt quy trình khẩn cấp đúng lúc.",en:"Assess on-site risks, give basic first aid and trigger emergency procedures in time."}},{name:{vi:"Minh bạch tài chính",en:"Financial transparency"},desc:{vi:"Quyết toán đúng chứng từ, từ chối hoa hồng ép khách mua hàng và báo cáo trung thực.",en:"Settle with correct receipts, refuse commissions that pressure guests to buy and report honestly."}}],knowledge:{vi:["Luật Du lịch số 09/2017/QH14: thẻ hướng dẫn viên quốc tế, nội địa, tại điểm và nghĩa vụ của hướng dẫn viên.","Công ước UNESCO năm 1972 về bảo vệ di sản văn hóa và thiên nhiên thế giới: di sản văn hóa, thiên nhiên, hỗn hợp.","Luật Di sản văn hóa năm 2024 và nội quy tham quan tại các khu di tích, danh thắng.","Lịch sử, văn hóa Việt Nam và các di sản thế giới như Huế, Hội An, Mỹ Sơn, Tràng An, Vịnh Hạ Long.","Sơ cấp cứu cơ bản và quy trình xử lý khách lạc, mất giấy tờ, tai nạn trong hành trình."],en:["Tourism Law No. 09/2017/QH14: international, domestic and on-site guide cards and guides' duties.","UNESCO 1972 World Heritage Convention: cultural, natural and mixed heritage.","Law on Cultural Heritage of 2024 and visitor rules at monuments and scenic sites.","Vietnamese history and culture and World Heritage sites such as Hue, Hoi An, My Son, Trang An and Ha Long Bay.","Basic first aid and procedures for lost guests, lost documents and accidents on tour."]},tools:["Bộ micro và tai nghe thuyết minh không dây","Ứng dụng nhắn tin nhóm đoàn","Bộ sơ cứu","Bảng quyết toán tạm ứng tour","Ứng dụng bản đồ và dự báo thời tiết"],kpis:{vi:["Điểm đánh giá của khách sau tour.","Tỷ lệ đúng giờ tại các điểm trong lịch trình.","Số sự cố an toàn trong tour (mục tiêu bằng 0).","Quyết toán đúng hạn, không sai sót chứng từ."],en:["Guest rating after the tour.","On-time rate at itinerary stops.","Safety incidents during the tour (target zero).","On-time settlement with no receipt errors."]},day:[{time:"07:00",vi:"Xem dự báo thời tiết, xác nhận xe, nhà hàng và vé tham quan trong ngày.",en:"Check the forecast and confirm the coach, restaurants and entry tickets for the day."},{time:"08:00",vi:"Đón khách tại khách sạn, kiểm đếm quân số, giới thiệu lịch trình và lưu ý an toàn.",en:"Meet guests at the hotel, count heads, present the plan and safety notes."},{time:"09:30",vi:"Thuyết minh tại điểm tham quan, mua vé theo đúng loại khách và giữ đoàn đúng giờ.",en:"Give site commentary, buy tickets by guest category and keep the group on time."},{time:"12:00",vi:"Ăn trưa cùng đoàn, kiểm tra yêu cầu ăn kiêng và dị ứng của khách.",en:"Have lunch with the group and check dietary and allergy needs."},{time:"17:00",vi:"Đưa khách về khách sạn, ghi nhận phản hồi, quyết toán chi phí và báo cáo điều hành.",en:"Return guests to the hotel, record feedback, settle costs and report to operations."}],mistakes:{vi:["Thuyết minh theo trí nhớ, nêu sai năm ghi danh hoặc loại hình di sản.","Mua vé người lớn cho trẻ em hoặc mua vé cho hướng dẫn viên đã được miễn.","Chiều khách tham gia hoạt động thiếu an toàn hoặc đưa khách vào điểm mua sắm ép giá để hưởng hoa hồng."],en:["Giving commentary from memory with wrong inscription years or heritage types.","Buying adult tickets for children or a ticket for a guide who enters free.","Letting guests join unsafe activities or taking them to overpriced shops for commission."]},career:[{vi:"Hướng dẫn viên tại điểm hoặc nội địa",en:"On-site or domestic guide"},{vi:"Hướng dẫn viên du lịch quốc tế",en:"International tour guide"},{vi:"Hướng dẫn viên chính tuyến cao cấp",en:"Senior lead guide for premium routes"},{vi:"Trưởng nhóm hướng dẫn viên, quản lý chất lượng dịch vụ",en:"Head of guides and service quality manager"}],glossary:[{term:"Mixed heritage",vi:"Di sản thế giới hỗn hợp, được công nhận đồng thời theo tiêu chí văn hóa và tiêu chí thiên nhiên.",en:"World Heritage site recognised under both cultural and natural criteria."},{term:"Tour leader",vi:"Trưởng đoàn đại diện cho khách hoặc công ty gửi khách, phối hợp với hướng dẫn viên địa phương.",en:"Group leader representing the guests or the sending company, working with the local guide."},{term:"Head count",vi:"Kiểm đếm quân số đoàn tại mỗi điểm dừng để không bỏ sót khách.",en:"Counting the group at each stop so no guest is left behind."},{term:"Cash advance",vi:"Khoản tạm ứng công ty giao cho hướng dẫn viên để chi trả dịch vụ trong tour.",en:"Money the company advances to the guide to pay for services on tour."},{term:"Commentary",vi:"Bài thuyết minh của hướng dẫn viên về lịch sử, văn hóa, thiên nhiên của điểm đến.",en:"The guide's narration on a destination's history, culture and nature."}],quiz:[{q:{vi:"Di sản thế giới nào ở Việt Nam là di sản hỗn hợp văn hóa và thiên nhiên?",en:"Which World Heritage site in Vietnam is a mixed cultural and natural site?"},options:{vi:["Vịnh Hạ Long","Quần thể danh thắng Tràng An","Phố cổ Hội An","Vườn quốc gia Phong Nha - Kẻ Bàng"],en:["Ha Long Bay","Trang An Landscape Complex","Hoi An Ancient Town","Phong Nha - Ke Bang National Park"]},answer:1,explain:{vi:"Tràng An được ghi danh năm 2014 là di sản hỗn hợp; Hội An là di sản văn hóa, Hạ Long và Phong Nha - Kẻ Bàng là di sản thiên nhiên.",en:"Trang An was inscribed in 2014 as a mixed site; Hoi An is cultural, Ha Long and Phong Nha - Ke Bang are natural."}},{q:{vi:"Đoàn 10 người lớn và 4 trẻ em; vé người lớn 200.000 đồng, trẻ em 50%, hướng dẫn viên miễn vé. Tổng tiền vé là bao nhiêu?",en:"A group of 10 adults and 4 children; adult ticket 200,000 VND, children 50%, guide free. What is the ticket total?"},options:{vi:["2.400.000 đồng","2.800.000 đồng","3.000.000 đồng","2.600.000 đồng"],en:["2,400,000 VND","2,800,000 VND","3,000,000 VND","2,600,000 VND"]},answer:0,explain:{vi:"10 x 200.000 + 4 x 100.000 = 2.000.000 + 400.000 = 2.400.000 đồng; hướng dẫn viên không mua vé.",en:"10 x 200,000 + 4 x 100,000 = 2,000,000 + 400,000 = 2,400,000 VND; the guide buys no ticket."}},{q:{vi:"Một cửa hàng đề nghị trả bạn 20% hoa hồng nếu bạn giới thiệu với khách rằng hàng của họ là đồ thủ công làng nghề, dù nguồn gốc không rõ. Bạn làm gì?",en:"A shop offers you 20% commission if you tell guests its goods are village handicrafts, though their origin is unclear. What do you do?"},options:{vi:["Nhận vì khách tự quyết định mua","Nhận nhưng không giới thiệu nhiều","Đưa khách đến rồi để cửa hàng tự nói","Từ chối, không giới thiệu sai và báo điều hành"],en:["Accept because guests choose to buy","Accept but promote it less","Bring guests and let the shop talk","Refuse, never mislead guests and report to operations"]},answer:3,explain:{vi:"Giới thiệu sai nguồn gốc hàng hóa là lừa dối khách và vi phạm đạo đức nghề hướng dẫn viên.",en:"Misrepresenting product origin deceives guests and breaches a guide's professional ethics."}},{q:{vi:"Khi kiểm đếm tại điểm dừng, bạn phát hiện thiếu một khách. Việc đầu tiên nên làm là gì?",en:"At a stop, the head count is one short. What should you do first?"},options:{vi:["Cho xe chạy, khách sẽ tự bắt taxi","Đăng thông báo lên mạng xã hội","Giữ đoàn tại điểm an toàn, liên lạc với khách và báo điều hành, ban quản lý điểm","Chờ đến hết ngày rồi báo cáo"],en:["Leave; the guest will take a taxi","Post a notice on social media","Keep the group at a safe spot, contact the guest and alert operations and site management","Wait until the end of the day, then report"]},answer:2,explain:{vi:"Giữ đoàn ổn định, liên lạc ngay và kích hoạt hỗ trợ của điều hành, ban quản lý giúp tìm khách nhanh và an toàn.",en:"Keeping the group settled, calling at once and getting operations and site staff involved finds the guest quickly and safely."}}],tools_en:["Wireless tour guide microphone and headsets","Group messaging app","First aid kit","Tour advance settlement sheet","Maps and weather forecast apps"]}}})})(window.KKR);
